_Static_assert(sizeof(font_px18_10x18) == 3456,
               "font_px18_10x18 must stay 96 glyphs x 18 rows x 2 bytes");

//-- Private descriptor of the pixel-height faces, indexed by height_px - 10.
static const tft_ec11_font_px_face_t tft_ec11_font_px_faces[] = {
    {10, 8, 7, 1, font_px10_7x10},    /* 10 px */
    {11, 9, 8, 1, font_px11_8x11},    /* 11 px */
    {12, 10, 9, 2, font_px12_9x12},   /* 12 px */
    {13, 10, 9, 2, font_px13_9x13},   /* 13 px */
    {14, 12, 10, 2, font_px14_10x14}, /* 14 px */
    {15, 12, 10, 2, font_px15_10x15}, /* 15 px */
    {16, 12, 10, 2, font_px16_10x16}, /* 16 px */
    {17, 12, 10, 2, font_px17_10x17}, /* 17 px */
    {18, 12, 10, 2, font_px18_10x18}, /* 18 px */
};
//*-END-GENERATED-PX-TABLES-*//

//-- One row of the medium 7x12 face for character c. Returns 0 for a row
//-- outside the glyph box and a hollow box glyph for characters without a
//-- dedicated glyph (same placeholder idea as the 5x7 face).
uint8_t tft_ec11_font_medium_row(unsigned char c, uint8_t row)
{
  if (row > 11)
    return 0;
  c = fold_accented_letter(c);
  if (c >= ' ' && c <= '~')
    return font_medium_7x12[c - ' '][row];
  if (row == 0 || row == 11)
    return 0x7F;
  if (row == 5)
    return 0x55;
  return 0x41;
}

//-- One row of the large 8x16 face for character c. Returns 0 for a row
//-- outside the glyph box and a hollow box glyph for characters without a
//-- dedicated glyph (same placeholder idea as the 5x7 face).
uint8_t tft_ec11_font_large_row(unsigned char c, uint8_t row)
{
  if (row > 15)
    return 0;
  c = fold_accented_letter(c);
  if (c >= ' ' && c <= '~')
    return font_large_8x16[c - ' '][row];
  if (row == 0 || row == 15)
    return 0xFF;
  if (row == 7)
    return 0xAA;
  return 0x81;
}

//-- Resolve one requested pixel height (10..18) to its private face
//-- descriptor. Returns NULL for any height outside the supported range;
//-- callers must resolve the face once per draw and reuse the descriptor.
const tft_ec11_font_px_face_t* tft_ec11_font_px_lookup(int height_px)
{
  //-- 10..18 must stay the public TFT_EC11_FONT_MIN/MAX_HEIGHT_PX range
  //-- (this file is deliberately free of ESP-IDF includes so the host
  //-- font checker can compile it; the generated descriptor array holds
  //-- exactly these nine heights).
  if (height_px < 10 || height_px > 18)
  {
    return NULL;
  }
  return &tft_ec11_font_px_faces[height_px - 10];
}

//-- The monospaced advance of a pixel-height face, in pixels (0 for a
//-- NULL face). Every glyph of the face, including the space and the
//-- fallback glyph, occupies exactly this many pixels horizontally.
uint8_t tft_ec11_font_px_advance_px(const tft_ec11_font_px_face_t* face)
{
  return (face != NULL) ? face->advance_px : 0;
}

//-- The visible bitmap width of a pixel-height face, in pixels (0 for a
//-- NULL face). The monospaced advance is always at least one pixel wider;
//-- the remaining columns are the spacing columns kept free of regular
//-- ink by the design.
uint8_t tft_ec11_font_px_glyph_width_px(const tft_ec11_font_px_face_t* face)
{
  return (face != NULL) ? face->glyph_width_px : 0;
}

//-- One decoded row of a pixel-height face for character c, returned with
//-- the leftmost pixel at bit 15 so both stored row widths share one
//-- geometry. Rows outside the glyph canvas return 0; every byte without a
//-- dedicated glyph (after the same accent folding as the legacy faces)
//-- renders the face's dedicated hollow-box fallback glyph.
uint16_t tft_ec11_font_px_row(const tft_ec11_font_px_face_t* face, unsigned char c, uint8_t row)
{
  unsigned index;

  if (face == NULL || row >= face->height_px)
    return 0;
  c = fold_accented_letter(c);
  index = (c >= ' ' && c <= '~') ? (unsigned)(c - ' ') : 95u;
  if (face->row_bytes == 1)
  {
    return (uint16_t)((const uint8_t*)face->rows)[index * face->height_px + row] << 8;
  }
  return ((const uint16_t*)face->rows)[index * face->height_px + row];
}
